"appearance_facts": [
  {
    "location": "The state of California",
    "fact": "The polygon is filled with orange and labeled 'California'. It is located on the west coast."
  },
  {
    "location": "The state of Texas",
    "fact": "The polygon is filled with orange and labeled 'Texas'. It is located in the south-central region."
  },
  {
    "location": "The state of Florida",
    "fact": "The polygon is filled with purple and labeled 'Florida'. It is located in the southeast."
  },
  {
    "location": "States including New York, Pennsylvania, Illinois, Ohio, Michigan, Georgia, and North Carolina",
    "fact": "These polygons are filled with green and are labeled with their respective state names."
  },
  {
    "location": "The legend",
    "fact": "The legend displays five color swatches. The orange swatch corresponds to the '30+ M' range, which is the highest population category shown."
  },
  {
    "location": "The legend",
    "fact": "The purple swatch corresponds to the '20 - 30 M' range, which is the second-highest category."
  },
  {
    "location": "The legend",
    "fact": "The green swatch corresponds to the '10 - 20 M' range."
  },
  {
    "location": "The legend",
    "fact": "The blue and red swatches correspond to the '5 - 10 M' and '0 - 5 M' ranges, respectively."
  }
],
"printed_facts": [
  {
    "location": "Top center",
    "fact": "The title reads 'US Population by State (in Millions)'."
  },
  {
    "location": "Right side legend",
    "fact": "The legend lists population ranges: '0 - 5 M', '5 - 10 M', '10 - 20 M', '20 - 30 M', and '30+ M'."
  },
  {
    "location": "Map labels",
    "fact": "The labels 'California' and 'Texas' are printed on the orange-colored states."
  },
  {
    "location": "Map labels",
    "fact": "The label 'Florida' is printed on the purple-colored state."
  }
],
"public_definitions": [
  "The goal is to open the state detail record that should be routed into the highest-population public statistics follow-up workflow.",
  "The population dashboard is the evidence source for the routing decision.",
  "The options are to open the detail for California, Texas, or Florida."
],
